def investigate(context, acquire):
    receipts = context.get('receipts') or []
    seen = set()
    for receipt in receipts:
        query = receipt.get('query')
        if isinstance(query, dict):
            seen.add(repr(query.get('actions')))
    candidates = [
        [{'op': 'begin'}, {'op': 'put', 'id': 1000}, {'op': 'commit'}],
        [{'op': 'put', 'id': 1000}, {'op': 'begin'}, {'op': 'delete', 'id': 1000}, {'op': 'rollback'}],
        [{'op': 'put', 'id': 1}, {'op': 'put', 'id': 1000}, {'op': 'delete', 'id': 1}, {'op': 'delete', 'id': 1000}],
        [{'op': 'begin'}, {'op': 'put', 'id': 1}, {'op': 'commit'}, {'op': 'begin'}, {'op': 'put', 'id': 1000}, {'op': 'rollback'}],
        [{'op': 'put', 'id': 999}, {'op': 'begin'}, {'op': 'put', 'id': 1000}, {'op': 'commit'}],
        [{'op': 'put', 'id': 500}, {'op': 'delete', 'id': 500}, {'op': 'begin'}, {'op': 'put', 'id': 500}, {'op': 'commit'}],
        [{'op': 'begin'}, {'op': 'put', 'id': 1}, {'op': 'put', 'id': 2}, {'op': 'commit'}, {'op': 'delete', 'id': 1}],
        [{'op': 'put', 'id': 1000}, {'op': 'begin'}, {'op': 'delete', 'id': 1000}, {'op': 'commit'}]
    ]
    for actions in candidates:
        if repr(actions) not in seen:
            return {'query': {'actions': actions}, 'note': {'focus': 'AUTOINCREMENT sqlite_sequence persistence across commit/rollback and boundary id 1000', 'parent_bug': 'cursor.lastrowid is unsupported; use SELECT max(rowid) or last_insert_rowid()'}}
    return {'query': None, 'note': {'status': 'exhausted candidate set'}}

